      ll T = t[0];

      for(int j=1;j<=i;j++)T = gcd(T,t[j]);

      for(int j=0;j<=i;j++)t[j]/=T;

    }



    for(int i=0;i<n;i++)cout << t[i] << endl;

  }

}

